// 사진 보기: 보기 글자를 열쇠로 사진 표를 만든다. 보기 글자가 바뀌면 사진을 못 찾으므로 함께 고쳐야 한다.
function HERITAGE_PHOTO_SET(names){const out={};for(const n of names){const p=globalThis.HERITAGE_PHOTOS[n];if(!p)throw Error("등재되지 않은 사진: "+n);out[n]=p;}return out;}
